"use client";

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';

export default function InventoryModal({ onSaved }: { onSaved?: () => void }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState<any>({
    itemName: '',
    category: '',
    description: '',
    quantityAvailable: 0,
    unit: 'pcs',
    costPrice: 0,
    sellingPrice: 0,
    vendorName: '',
    vendorContact: '',
    isGstApplicable: false,
    vendorGstNumber: '',
    gstPercentage: 0,
  });

  const handleChange = (k: string, v: any) => setForm((s: any) => ({ ...s, [k]: v }));

  const submit = async () => {
    const payload: any = {
      itemName: form.itemName,
      category: form.category,
      description: form.description,
      quantityAvailable: Number(form.quantityAvailable) || 0,
      unit: form.unit,
      costPrice: Number(form.costPrice) || 0,
      sellingPrice: Number(form.sellingPrice) || 0,
      vendorName: form.vendorName,
      vendorContact: form.vendorContact,
    };
    if (form.isGstApplicable) {
      payload.vendorGstNumber = form.vendorGstNumber;
      payload.gstPercentage = Number(form.gstPercentage) || 0;
    }
    try {
      const res = await fetch('/api/inventory', { method: 'POST', body: JSON.stringify(payload), headers: { 'Content-Type': 'application/json' } });
      if (!res.ok) throw new Error('Failed');
      setOpen(false);
      setForm({ itemName: '', category: '', description: '', quantityAvailable: 0, unit: 'pcs', costPrice: 0, sellingPrice: 0, vendorName: '', vendorContact: '', isGstApplicable: false, vendorGstNumber: '', gstPercentage: 0 });
      onSaved && onSaved();
    } catch (e) {
      console.error(e);
      alert('Failed to save inventory');
    }
  };

  return (
    <>
      <Button onClick={() => setOpen(true)}>+ Add Inventory</Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Inventory</DialogTitle>
          </DialogHeader>
          <div className="grid gap-2">
            <div>
              <Label>Item Name</Label>
              <Input value={form.itemName} onChange={(e: any) => handleChange('itemName', e.target.value)} />
            </div>
            <div>
              <Label>Category</Label>
              <Input value={form.category} onChange={(e: any) => handleChange('category', e.target.value)} />
            </div>
            <div>
              <Label>Description</Label>
              <Input value={form.description} onChange={(e: any) => handleChange('description', e.target.value)} />
            </div>
            <div>
              <Label>Quantity Available</Label>
              <Input type="number" value={form.quantityAvailable} onChange={(e: any) => handleChange('quantityAvailable', e.target.value)} />
            </div>
            <div>
              <Label>Unit</Label>
              <Input value={form.unit} onChange={(e: any) => handleChange('unit', e.target.value)} />
            </div>
            <div>
              <Label>Cost Price</Label>
              <Input type="number" value={form.costPrice} onChange={(e: any) => handleChange('costPrice', e.target.value)} />
            </div>
            <div>
              <Label>Selling Price</Label>
              <Input type="number" value={form.sellingPrice} onChange={(e: any) => handleChange('sellingPrice', e.target.value)} />
            </div>
            <div>
              <Label>Vendor Name</Label>
              <Input value={form.vendorName} onChange={(e: any) => handleChange('vendorName', e.target.value)} />
            </div>
            <div>
              <Label>Vendor Contact (optional)</Label>
              <Input value={form.vendorContact} onChange={(e: any) => handleChange('vendorContact', e.target.value)} />
            </div>
            <div className="flex items-center gap-3">
              <Label>Is GST Applicable?</Label>
              <Switch checked={form.isGstApplicable} onCheckedChange={(v: any) => handleChange('isGstApplicable', v)} />
            </div>
            {form.isGstApplicable && (
              <>
                <div>
                  <Label>Vendor GST Number</Label>
                  <Input value={form.vendorGstNumber} onChange={(e: any) => handleChange('vendorGstNumber', e.target.value)} />
                </div>
                <div>
                  <Label>GST Percentage</Label>
                  <Input type="number" value={form.gstPercentage} onChange={(e: any) => handleChange('gstPercentage', e.target.value)} />
                </div>
              </>
            )}
          </div>
          <DialogFooter>
            <Button variant="secondary" onClick={() => setOpen(false)}>Cancel</Button>
            <Button onClick={submit}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}
